// Command snapshot writes the bundled library's snapshot and the Go file that
// embeds it into package libs; run through `go generate ./internal/workspace/libs`.
package main

import (
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"path/filepath"

	"github.com/Open-MBEE/OpenSysML/internal/workspace/libs"
	"github.com/Open-MBEE/OpenSysML/tools/oracle/repo"
)

// libsDir is package libs, relative to the repository root: where both files
// are written unless -dir says otherwise.
const libsDir = "internal/workspace/libs"

// snapshotName and embedName are the two generated files, both gitignored.
const (
	snapshotName = "stdlib.snapshot"
	embedName    = "snapshot_embedded.go"
)

// embedSource is embedName: the init that hands the embedded bytes to the
// stdlibSnapshot variable of snapshot.go, which stays nil without this file.
const embedSource = `// Code generated by tools/gen/snapshot; DO NOT EDIT.

package libs

import _ "embed"

// embeddedSnapshot is ` + snapshotName + `, the generated snapshot of the bundled
// library that stdlibSnapshot documents.
//
//go:embed ` + snapshotName + `
var embeddedSnapshot []byte

func init() { stdlibSnapshot = embeddedSnapshot }
`

// logPrefix opens every diagnostic the tool writes.
const logPrefix = "snapshot:"

func main() {
	os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
}

// run is main without the process exit, so tests can drive it in-process.
func run(args []string, stdout, stderr io.Writer) int {
	flags := flag.NewFlagSet("snapshot", flag.ContinueOnError)
	flags.SetOutput(stderr)
	dir := flags.String("dir", "", "directory to write "+snapshotName+" and "+embedName+" to (default "+libsDir+" under the repository root)")
	if err := flags.Parse(args); errors.Is(err, flag.ErrHelp) {
		return 0
	} else if err != nil {
		return 2
	}
	if repo.NeedsRoot(*dir) {
		root, err := repo.Root()
		if err != nil {
			fmt.Fprintln(stderr, logPrefix, err)
			return 1
		}
		*dir = repo.Resolve(root, *dir)
		if *dir == "" {
			*dir = filepath.Join(root, filepath.FromSlash(libsDir))
		}
	}

	data, err := libs.BuildSnapshot(libs.BundledSource())
	if err != nil {
		fmt.Fprintln(stderr, logPrefix, err)
		return 1
	}
	snapshot := filepath.Join(*dir, snapshotName)
	if err := os.WriteFile(snapshot, data, 0o600); err != nil {
		fmt.Fprintln(stderr, logPrefix, err)
		return 1
	}
	if err := os.WriteFile(filepath.Join(*dir, embedName), []byte(embedSource), 0o600); err != nil {
		fmt.Fprintln(stderr, logPrefix, err)
		return 1
	}
	fmt.Fprintf(stdout, "wrote %s (%d bytes) and %s\n", snapshot, len(data), embedName)
	return 0
}
